#!/usr/bin/env python3
"""
Round 170b (culprits), 4 October 2026. Needs round 169n.

Basemap menu renamed and reordered; one note style; Woodlands note wording.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 170b (4 October)\n\nNeeds round 169n (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- Asked 4 October: the basemap menu named and ordered Jurassic, Atlas,\n  Woodlands, Bioluminescent, Earth at Night, Hologram, Hell, Standard.\n  Jurassic = Satellite imagery (key satellite), Bioluminescent = Deep space\n  (space), Standard = Country outlines (outlines), Earth at Night (night),\n  Hologram view now "Hologram". One block after Earth at night ("The basemap\n  menu: names and order", BASEMAP_MENU) passes the whole list to the wrappers\n  so their order holds; the hologram switch in index.html is put before Hell.\n- Old fantasy painting (dusk) is out of the menu; its code is left unused.\n  Mother Earth was already removed in 168p.\n- Every basemap (i) note uses the Woodlands box (bmNoteCss); the card frame is\n  gone. Woodlands\' note: "the Native peoples who live in them".\n']

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round170b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 169n" not in h.read_text(encoding="utf-8"):
        sys.exit("round170b: round 169n must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round170b: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round170b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round170b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
